                                <button
                                    onClick={() => setShowSettings(true)}
                                    aria-label="Open device and AI settings"
                                    className="flex size-11 items-center justify-center rounded-xl bg-white/10 text-white transition hover:scale-105 hover:bg-white/20 active:scale-95 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white"
                                >
                                    <Settings size={20} />
                                </button>
